import type Database from 'better-sqlite3'

/** SQL migrations generated by drizzle-kit (`npm run db:generate`), bundled at build time. */
const files = import.meta.glob('./migrations/*.sql', {
  query: '?raw',
  import: 'default',
  eager: true
}) as Record<string, string>

export function migrations(): { name: string; sql: string }[] {
  return Object.entries(files)
    .map(([path, sql]) => ({
      name: path
        .split('/')
        .pop()!
        .replace(/\.sql$/, ''),
      sql
    }))
    .sort((a, b) => a.name.localeCompare(b.name))
}

/** Apply any migrations that haven't run yet, each in its own transaction. */
export function migrate(sqlite: Database.Database): string[] {
  sqlite.exec('CREATE TABLE IF NOT EXISTS __migrations (name TEXT PRIMARY KEY, applied_at INTEGER NOT NULL)')
  const done = new Set(
    (sqlite.prepare('SELECT name FROM __migrations').all() as { name: string }[]).map((r) => r.name)
  )
  const applied: string[] = []
  for (const m of migrations()) {
    if (done.has(m.name)) continue
    const statements = m.sql
      .split('--> statement-breakpoint')
      .map((s) => s.trim())
      .filter(Boolean)
    sqlite.transaction(() => {
      for (const st of statements) sqlite.exec(st)
      sqlite.prepare('INSERT INTO __migrations (name, applied_at) VALUES (?, ?)').run(m.name, Date.now())
    })()
    applied.push(m.name)
  }
  return applied
}
